begin;
update news set body = body || '["Türkiye açısından bakarsak: vivo''nun V serisi burada da satılıyor; kataloğumuzdaki V40 yaklaşık 29 bin TL''den listeleniyor. V80 Türkiye''ye gelirse 7.200 mAh pil ve IP69 dayanıklılıkla POCO X7 Pro (6.000 mAh, IP68) ve Galaxy A56 (IP67, 6 yıl güncelleme sözü) gibi modellerle aynı bantta yarışması beklenir. Bu sınıfta kâğıt üzerindeki donanım kadar yazılım güncelleme süresi ve servis ağı da kararı belirliyor."]'::jsonb where id = 'vivo-v80-tanitildi-zeiss-kameralar-144-hz-ekran-ve-7-200-mah-batarya';
update news set body = body || '["Güncelleme: Watch GT 7 ailesi Türkiye''de de satışta. Kataloğumuzda standart GT 7 yaklaşık 15.700 TL, GT 7 Pro ise yaklaşık 20.600 TL fiyatla yer alıyor. Pil tarafında GT 7''nin vaat ettiği süreler, her gece şarj isteyen Apple Watch ve bir buçuk-iki günde şarj isteyen Galaxy Watch modellerinden çok uzun; bu açıdan rakipleri daha çok Amazfit Balance 2 gibi uzun pilli saatler. iPhone ile de çalışıyor, ancak mesajlara yanıt verme gibi bazı özellikler iOS''ta sınırlı kalabiliyor."]'::jsonb where id = 'huawei-watch-gt-7-serisi-tanitildi-21-gun-pil';
update news set body = body || '["Redmi K serisi Türkiye''de kendi adıyla satılmıyor, ancak önceki K modelleri küresel pazara çoğunlukla POCO F adıyla geldi; örneğin Redmi K70, dünyada POCO F6 Pro olarak satıldı. K100''ün de benzer bir yol izlemesi olası, fakat bu henüz doğrulanmış değil. Referans olması için: kataloğumuzda POCO F9 Pro yaklaşık 70 bin, F9 Ultra ise yaklaşık 80 bin TL''den listeleniyor."]'::jsonb where id = 'redmi-k100-10-000-mah-bataryayla-geliyor-100-w-sarj-ve-165-hz-ekran';
update news set body = body || '["Türkiye''deki kullanıcılar için bir referans noktası: kataloğumuzda önceki nesil OnePlus 13 yaklaşık 55 bin TL, OnePlus 12 ise yaklaşık 35 bin TL fiyatla yer alıyor. OnePlus 16''nın burada satışa çıkıp çıkmayacağı belli değil; çıkarsa bellek fiyatlarındaki artış nedeniyle OnePlus 13''ten daha yüksek bir fiyat etiketiyle gelmesi şaşırtıcı olmaz."]'::jsonb where id = 'oneplus-16-icin-lansman-tarihi-aciklandi-yeni-snapdragon-islemci-geliyor';
update news set body = body || '["Fitbit ürünleri Türkiye''de satılıyor ve kataloğumuzda Charge 6 yaklaşık 5 bin, Versa 4 yaklaşık 7 bin, Sense 2 ise yaklaşık 9 bin TL fiyatla yer alıyor. Edge''in Türkiye''ye gelip gelmeyeceği açıklanmadı; gelirse değiştirilebilir bataryası, şarj sağlığı ve cihazın kullanım ömrü açısından mevcut Fitbit modellerinde olmayan bir avantaj sunacak."]'::jsonb where id = 'google-fitbit-edge-tanitildi-bir-hafta-pil-ve-degistirilebilen-batarya';
update news set body = body || '["Fiyat beklentisi için bir referans: kataloğumuzda OPPO''nun bir önceki kamera amiral gemisi Find X7 Ultra yaklaşık 70 bin TL''den listeleniyor. Find X10 Pro Max''in Avrupa''ya gelmesi Türkiye için de bir ihtimal doğuruyor, ancak OPPO henüz Türkiye satışına dair bir açıklama yapmadı."]'::jsonb where id = 'oppo-find-x10-pro-max-avrupa-ya-geliyor-uclu-200-mp-kamera-ve-8-000-mah-batarya';
update news set body = body || '["Samsung''un mevcut serisinde kulak kanalını tamamen kapatmayan bir model zaten var: Galaxy Buds3, açık tasarımıyla kulak içi kulaklıkları rahatsız edici bulanlara yönelik. Buds On bu yaklaşımı bir adım öteye taşıyarak kulak kanalına hiç girmeyen bir yapı sunuyor. Bu tür tasarımlar çevreyi duymak isteyen koşucular ve uzun süre kulaklık takanlar için rahat, ancak gürültülü ortamlarda bas performansı ve ses yalıtımı kulak içi modellerin gerisinde kalıyor."]'::jsonb where id = 'samsung-galaxy-buds-on-tanitildi-kulak-ici-yerine-kulak-ustune-tutan-tasarim';
update news set image_url = 'https://www.nvidia.com/content/dam/en-zz/Solutions/dgx-spark/nvidia-dgx-spark-family-og.jpg', image_credit = 'NVIDIA' where id = 'nvidia-dgx-spark-in-64-gb-versiyonu-geliyor-yerel-yapay-zeka-icin-daha-erisilebilir-secenek';
update news set image_url = 'https://in-exstatic-vivofs.vivo.com/gdHFRinHEMrj3yPG/product/1792408487419/zip/img/vivo-v80-lg-x2.jpg', image_credit = 'vivo' where id = 'vivo-v80-tanitildi-zeiss-kameralar-144-hz-ekran-ve-7-200-mah-batarya';
update news set image_url = 'https://in-exstatic-vivofs.vivo.com/gdHFRinHEMrj3yPG/product/1793784018930/zip/images/kv-vivo-x-fold6-pc-q80.avif', image_credit = 'vivo' where id = 'vivo-x-fold6-hindistan-da-8-02-inc-katlanabilir-ekranli-model-13-ekim-de-satisa-cikiyor';
commit;
select id, image_credit, jsonb_array_length(body) n from news where id in ('nvidia-dgx-spark-in-64-gb-versiyonu-geliyor-yerel-yapay-zeka-icin-daha-erisilebilir-secenek','vivo-v80-tanitildi-zeiss-kameralar-144-hz-ekran-ve-7-200-mah-batarya','vivo-x-fold6-hindistan-da-8-02-inc-katlanabilir-ekranli-model-13-ekim-de-satisa-cikiyor') or id like 'oneplus-16-icin%' or id like 'redmi-k100%';